import React from 'react';
import { createRoot } from 'react-dom/client';
import { act } from 'react';
import office from './__fixtures__/office.json';
import four from './__fixtures__/fourSeats.json';
jest.mock('../../lib/liveCandles', () => ({ useLiveCandles: () => null }));   // no network in tests
jest.mock('../terminal/PriceChart', () => ({ PriceChart: () => <div data-testid="price-chart" /> }));   // the live chart needs a canvas

// 🪑 the four-seat operating model on the page: every number comes from the payload fixture generated by the real backend functions
// (seat_ops.seat_board / summary + social_research.research on the HTML fixtures) — nothing here is computed by the page.
const O = { ...office, ...four };
const mount = async node => { const el = document.createElement('div'); document.body.appendChild(el); await act(async () => { createRoot(el).render(node); }); return el; };
const q = (el, id) => el.querySelector(`[data-testid="${id}"]`);
const click = async node => { await act(async () => { node.dispatchEvent(new MouseEvent('click', { bubbles: true })); }); };

test('🆕 fresh pipeline block: buckets, repeats, age at entry, candle allocation, top 5', async () => {
  const { FreshBlock } = require('./SeatOps');
  const el = document.createElement('div'); document.body.appendChild(el);
  const { createRoot } = require('react-dom/client'); const { act } = require('react');
  await act(async () => { createRoot(el).render(<FreshBlock f={{ buckets: { '0–5m': 4, '6h+': 2 }, deep: { '0–5m': 3 }, cleared: {}, unique: 30, repeats: 12, newUnique: 18, cooled: 5,
    ageReviewedMin: 40, boughtAgeMin24h: 50, boughtAgeMinBefore: 2900, bought24h: 3, candles: { allocFirst: { fresh: 20, old: 4, held: 0 }, allocBefore: { fresh: 6, old: 14, held: 4 } },
    top: [{ symbol: 'BABY', ageMin: 7, mc: 64000, src: ['pulse'], vpm: 1200, bpm: 3.1, tier: 'A', score: 71 }] }} />); });
  expect(el.textContent).toContain('30 · 12 · 18 · 5'); expect(el.textContent).toContain('50m vs 2d'); expect(el.textContent).toContain('20 / 4 / 0');
  expect(el.textContent).toContain('$BABY'); expect(el.textContent).toContain('pulse');
});

test('🗂 active index + 📡 RPC lanes render the canonical candidates and lane health (no URLs)', async () => {
  const { ActiveIndex, RpcLanes } = require('./SeatOps');
  const el = document.createElement('div'); document.body.appendChild(el);
  const { createRoot } = require('react-dom/client'); const { act } = require('react');
  await act(async () => { createRoot(el).render(<div><RpcLanes r={{ lanes: [{ lane: 1, provider: 'alchemy.com', spent: false }, { lane: 2, provider: 'helius-rpc.com', spent: true, backInMin: 40 }], note: 'n' }} />
    <ActiveIndex rows={[{ mint: 'A', symbol: 'BABY', eligible: true, launchAgeMin: 6, liveMC: 52000, volVelocity: 900, buyerVelocity: 3, holderStatus: 'passed', realCandles: true, chartQuality: 'EARLY', marketPhase: 'EARLY MOVE', sources: ['pulse'], cooldownLeft: 0 },
      { mint: 'B', symbol: 'OLDY', eligible: false, why: 'dead — $40 traded in the last 5 min', launchAgeMin: 3000, holderStatus: 'passed', sources: [] }]} /></div>); });
  expect(el.textContent).toContain('alchemy.com'); expect(el.textContent).toContain('out of quota · back in 40m');
  expect(el.textContent).toContain('1 eligible / 2'); expect(el.textContent).toContain('$BABY'); expect(el.textContent).toContain('dead — $40');
});

test('the kernel board: four hunter lanes, Devil warnings never read as a block, market vs decision freshness apart', async () => {
  const { KernelBoard } = require('./SeatOps');
  const el = document.createElement('div'); document.body.appendChild(el);
  const o = { kernel: { lanes: [{ lane: 1, state: 'HELD', symbol: 'AAA' }, { lane: 2, state: 'ARMED', symbol: 'BBB' }, { lane: 3, state: 'HUNTING', symbol: 'CCC' }, { lane: 4, state: 'HUNTING' }],
    candidates: [{ mint: 'b', symbol: 'BBB', pair: 'Pb', status: 'READY', rank: 180, narrative: 'HOT EARLY MOVE', trigger: 'ENTER', devil: [['rug_signs', 'STRONG_WARNING', 'x'], ['identity', 'WARNING', 'no site']], size: 0.75, courier: true,
      unknown: ['holders'], decidedAgo: 4, ages: { price: 2, research: null } }] } };
  await act(async () => { createRoot(el).render(<KernelBoard o={o} />); });
  expect(el.querySelectorAll('[data-testid^="hunter-"]')).toHaveLength(4);
  expect(el.querySelector('[data-testid="hunter-2"]').textContent).toContain('ARMED · $BBB');
  const dv = el.querySelector('[data-testid="kc-devil-BBB"]').textContent;
  expect(dv).toContain('⚠ DEVIL WARNS'); expect(dv).not.toContain('VETO'); expect(el.textContent).not.toContain('BLOCKED');
  expect(el.querySelector('[data-testid="kc-fresh-BBB"]').textContent).toContain('decision 4s ago'); expect(el.querySelector('[data-testid="kc-fresh-BBB"]').textContent).toContain('market 2s ago');
});
